import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), bird = sc.nextInt();
        int[] forest = new int[n];
        for (int i = 0; i < n; i++) forest[i] = sc.nextInt();
        // Sticks on each side ordered from nearest to farthest from the fixed nest.
        List<Integer> left = new ArrayList<>(), right = new ArrayList<>();
        for (int i = bird - 1; i >= 0; i--)
            if (forest[i] != 0) left.add(i);
        for (int i = bird + 1; i < n; i++)
            if (forest[i] != 0) right.add(i);
        List<Integer> answer = new ArrayList<>();
        long total = 0;
        while (total < 100) {
            List<Integer> side = answer.size() % 2 == 0 ? right : left;
            int index = side.get(answer.size() / 2);
            answer.add(index);
            total += forest[index];
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < answer.size(); i++) sb.append(i > 0 ? " " : "").append(answer.get(i));
        System.out.println(sb);
    }
}

package main

import (
	"fmt"
	"strconv"
	"strings"
)

func main() {
	var n, bird int
	fmt.Scan(&n, &bird)
	forest := make([]int, n)
	for i := range forest {
		fmt.Scan(&forest[i])
	}
	// Sticks on each side ordered from nearest to farthest from the fixed nest.
	var left, right []int
	for i := bird - 1; i >= 0; i-- {
		if forest[i] != 0 {
			left = append(left, i)
		}
	}
	for i := bird + 1; i < n; i++ {
		if forest[i] != 0 {
			right = append(right, i)
		}
	}
	var answer []string
	total := 0
	for total < 100 {
		side := right
		if len(answer)%2 == 1 {
			side = left
		}
		index := side[len(answer)/2]
		answer = append(answer, strconv.Itoa(index))
		total += forest[index]
	}
	fmt.Println(strings.Join(answer, " "))
}
